# Function to recursively copy files and write their paths to log file
function Copy-Files {
    param (
        [Parameter(Mandatory=$true)] [string]$source,
        [Parameter(Mandatory=$true)] [string]$destination
    )
    Get-ChildItem $source -Recurse | Foreach-Object {
        $destinationPath = Join-Path $destination $_.FullName.SubString($source.Length)
        if (-not (Test-Path -Path $destinationPath)) {
            New-Item -ItemType File -Path $destinationPath -Force
            $_ | Out-File -Append $logFile
        }
        else {
            $_ | Out-File -Append $logFile
        }
        Copy-Item $_.FullName -Destination $destinationPath -Force
    }
}

